for i,r in enumerate(inp,1):
    if len(r)!=26: print("short row", i, len(r))
# Hypothesis: the 4 in row 7 is at col 23 (one more zero before it)
inp[6].insert(21, 0)  # insert 0 before position of 4 (0-indexed 21)
print(len(inp[6]), [(r,c,inp[r-1][c-1]) for r in range(1,17) for c in range(1,27) if inp[r-1][c-1] not in (0,8)])

def rot90cw(k, n=3):
    out = {}
    for (r,c),v in k.items():
        out[(c, n+1-r)] = v
    return out

# key relative cells (bbox rows7-9, cols22-24)
rel = {(r-6, c-21): v for r,c,v in [(7,23,4),(8,23,4),(8,24,2),(9,22,3),(9,24,2)]}
rot = rot90cw(rel)
print("rotated:", sorted(rot.items()))
# shape blocks (4x4): (band, blockcol) -> (rows, cols)
blocks = {(1,1):(4,7,3,6), (2,2):(8,11,7,10), (2,3):(8,11,11,14), (3,1):(12,15,3,6), (3,2):(12,15,7,10)}
shape_layout = {(1,1),(2,2),(2,3),(3,1),(3,2)}
print("match:", set(rot.keys()) == shape_layout)

out = [row[:] for row in inp]
for (b, blk) in blocks.items():
    r1,r2,c1,c2 = blk
    col = rot[b]
    for r in range(r1, r2+1):
        for c in range(c1, c2+1):
            out[r-1][c-1] = col
for r in out: print(' '.join(map(str,r)))
